/* Browser-local desktop layout and reversible folder deletion. */
(() => {
const workspace=document.querySelector('.workspace');if(!workspace)return;
const files=[...workspace.querySelectorAll('.desktop-file')],key='po-desktop-folders-v1';
const valid=new Set(files.map(f=>f.querySelector('[data-open]').dataset.open));
let state={positions:{wide:{},mobile:{}},deleted:[]},storageAvailable=true,drag=null,suppressClick=false,selected=null,menuKey=null,lastDelete=null;
try{const saved=JSON.parse(localStorage.getItem(key)||'null');if(saved&&typeof saved==='object'){for(const mode of ['wide','mobile'])for(const [id,p] of Object.entries(saved.positions?.[mode]||{})){if(valid.has(id)&&Number.isFinite(p.x)&&Number.isFinite(p.y))state.positions[mode][id]={x:Math.max(0,Math.min(1,p.x)),y:Math.max(0,Math.min(1,p.y))};}state.deleted=Array.isArray(saved.deleted)?saved.deleted.filter(id=>valid.has(id)):[]}}catch{storageAvailable=false}
const mode=()=>innerWidth<=700?'mobile':'wide';
function persist(){try{localStorage.setItem(key,JSON.stringify(state))}catch{storageAvailable=false;notify('Your desktop changed for this visit. Browser storage is unavailable.')}}
const trash=document.createElement('button');trash.className='dock-icon macos-app dock-trash';trash.setAttribute('aria-label','Trash');trash.innerHTML='<svg class="trash-art" viewBox="0 0 48 56" aria-hidden="true"><defs><linearGradient id="trash-glass" x2="1" y2="1"><stop stop-color="#fff" stop-opacity=".95"/><stop offset="1" stop-color="#bfd5e6" stop-opacity=".7"/></linearGradient></defs><path d="M8 12H40L36 49Q35 53 31 53H17Q13 53 12 49Z" fill="url(#trash-glass)" stroke="#fff" stroke-opacity=".8"/><ellipse cx="24" cy="12" rx="16" ry="4" fill="#9cb2c4" stroke="#fff" stroke-opacity=".8"/><path d="M17 23L19 43M24 23V44M31 23L29 43" stroke="#7b98ad" stroke-opacity=".5" stroke-width="1.3"/><g class="trash-paper"><path d="M15 24L27 19 34 36 21 41Z" fill="#edf5fc"/><path d="M18 26L27 23M20 30L29 27M22 34L30 31" stroke="#86a6bf" stroke-width="1.2"/></g></svg><span class="trash-count" aria-hidden="true"></span><small>Trash</small>';document.querySelector('.dock').append(trash);dockIcons.push(trash);
const menu=document.createElement('div');menu.className='folder-context-menu';menu.hidden=true;menu.setAttribute('role','menu');menu.setAttribute('aria-label','Folder actions');menu.innerHTML='<button role="menuitem" data-folder-action="open">Open folder <span>↗</span></button><button role="menuitem" data-folder-action="reset">Reset position <span>↺</span></button><hr><button role="menuitem" data-folder-action="delete">Move to Trash <span>⌫</span></button>';document.body.append(menu);
const bin=document.createElement('dialog');bin.className='desktop-trash-window';bin.setAttribute('aria-labelledby','trash-title');bin.innerHTML='<header><div><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M6 7H18L17 21H7ZM4 7H20M9 7V3H15V7" fill="none" stroke="currentColor" stroke-width="1.4"/></svg><h2 id="trash-title">Trash</h2></div><button id="trash-close" aria-label="Close Trash">×</button></header><p class="trash-description">Folders moved here are hidden from this desktop. You can restore them anytime.</p><div id="trash-items"></div><footer><span id="trash-status"></span><button id="trash-restore-all">Restore all</button></footer>';document.body.append(bin);
const undo=document.createElement('div');undo.className='folder-undo';undo.hidden=true;undo.setAttribute('role','status');undo.innerHTML='<span></span><button id="folder-undo">Undo</button><button id="folder-undo-dismiss" aria-label="Dismiss">×</button>';document.body.append(undo);
function idOf(file){return file.querySelector('[data-open]').dataset.open}
function fileOf(id){return files.find(f=>idOf(f)===id)}
function nameOf(file){return file.querySelector('.file-name').textContent}
function select(file){selected=file;files.forEach(f=>f.classList.toggle('folder-selected',f===file))}
function layout(){for(const file of files){const id=idOf(file);file.hidden=state.deleted.includes(id);file.classList.remove('folder-positioned');file.style.removeProperty('--folder-dx');file.style.removeProperty('--folder-dy');if(file.hidden)continue;const p=state.positions[mode()][id];if(p){const base=file.getBoundingClientRect(),area=workspace.getBoundingClientRect(),maxX=Math.max(0,area.width-base.width),maxY=Math.max(0,area.height-base.height-90);file.style.setProperty('--folder-dx',(p.x*maxX-(base.left-area.left))+'px');file.style.setProperty('--folder-dy',(p.y*maxY-(base.top-area.top))+'px');file.classList.add('folder-positioned')}}updateBin()}
function updateBin(){const count=state.deleted.length;trash.classList.toggle('has-items',count>0);trash.setAttribute('aria-label',`Trash, ${count} ${count===1?'folder':'folders'}`);trash.querySelector('.trash-count').textContent=count||'';if(bin.open)renderBin()}
function closeMenu(focus=false){menu.hidden=true;if(focus&&menuKey)fileOf(menuKey)?.querySelector('[data-open]').focus({preventScroll:true})}
function showMenu(id,x,y){menuKey=id;menu.hidden=false;const r=menu.getBoundingClientRect();menu.style.left=Math.max(8,Math.min(x,innerWidth-r.width-8))+'px';menu.style.top=Math.max(8,Math.min(y,innerHeight-r.height-8))+'px';menu.querySelector('button').focus({preventScroll:true})}
function remove(id){if(state.deleted.includes(id))return;const file=fileOf(id);if(!file)return;lastDelete=id;state.deleted.push(id);file.hidden=true;persist();updateBin();closeMenu();undo.querySelector('span').textContent=`“${nameOf(file)}” moved to Trash`;undo.hidden=false;trash.focus({preventScroll:true});window.PortfolioMotion?.spring(trash,.85,1);}
function restore(id){state.deleted=state.deleted.filter(v=>v!==id);if(lastDelete===id){lastDelete=null;undo.hidden=true}persist();layout();const file=fileOf(id);if(file&&!file.hidden)window.PortfolioMotion?.spring(file,.85,1);}
function renderBin(){const area=bin.querySelector('#trash-items');area.replaceChildren();if(!state.deleted.length){const p=document.createElement('p');p.className='trash-empty';p.textContent='All clear. Your folders are on the desktop.';area.append(p)}for(const id of state.deleted){const file=fileOf(id),row=document.createElement('div');row.className='trash-row';const image=document.createElement('img');image.src='assets/tahoe/folder.svg';image.alt='';const label=document.createElement('span');label.textContent=nameOf(file);const button=document.createElement('button');button.textContent='Restore';button.setAttribute('aria-label',`Restore ${nameOf(file)}`);button.onclick=()=>restore(id);row.append(image,label,button);area.append(row)}bin.querySelector('#trash-status').textContent=`${state.deleted.length} ${state.deleted.length===1?'folder':'folders'} · This browser only`;bin.querySelector('#trash-restore-all').disabled=!state.deleted.length;}
trash.onclick=()=>{renderBin();bin.showModal();};bin.querySelector('#trash-close').onclick=()=>bin.close();bin.querySelector('#trash-restore-all').onclick=()=>{state.deleted=[];lastDelete=null;undo.hidden=true;persist();layout();notify('All folders restored to your desktop.')};undo.querySelector('#folder-undo').onclick=()=>{if(lastDelete)restore(lastDelete)};undo.querySelector('#folder-undo-dismiss').onclick=()=>{undo.hidden=true};
for(const file of files){file.classList.add('folder-managed');const button=file.querySelector('[data-open]');button.setAttribute('aria-describedby','folder-drag-hint');button.draggable=false;const options=document.createElement('button');options.className='folder-options';options.setAttribute('aria-label',`Options for ${nameOf(file)}`);options.setAttribute('aria-haspopup','menu');options.textContent='•••';options.onclick=e=>{e.stopPropagation();const r=options.getBoundingClientRect();select(file);showMenu(idOf(file),r.right,r.bottom+5)};file.append(options);
 file.addEventListener('dragstart',e=>e.preventDefault());
 file.addEventListener('contextmenu',e=>{e.preventDefault();select(file);showMenu(idOf(file),e.clientX,e.clientY)});
 button.addEventListener('pointerdown',e=>{if(e.button!==0||file.hidden)return;closeMenu();select(file);const rect=file.getBoundingClientRect();drag={id:idOf(file),file,button,pointer:e.pointerId,startX:e.clientX,startY:e.clientY,rect,started:false,dx:parseFloat(file.style.getPropertyValue('--folder-dx'))||0,dy:parseFloat(file.style.getPropertyValue('--folder-dy'))||0};});
 button.addEventListener('keydown',e=>{if(e.key==='Delete'||e.key==='Backspace'){e.preventDefault();e.stopPropagation();remove(idOf(file));return}if(e.key==='ContextMenu'||e.key==='F10'&&e.shiftKey){e.preventDefault();const r=file.getBoundingClientRect();showMenu(idOf(file),r.left+30,r.bottom-10);return}if(e.altKey&&['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key)){e.preventDefault();const rect=file.getBoundingClientRect(),area=workspace.getBoundingClientRect(),step=e.shiftKey?40:12;const x=rect.left-area.left+(e.key==='ArrowRight'?step:e.key==='ArrowLeft'?-step:0),y=rect.top-area.top+(e.key==='ArrowDown'?step:e.key==='ArrowUp'?-step:0);savePosition(file,x,y);layout();}});
}
function savePosition(file,x,y){const area=workspace.getBoundingClientRect(),rect=file.getBoundingClientRect(),maxX=Math.max(0,area.width-rect.width),maxY=Math.max(0,area.height-rect.height-90);state.positions[mode()][idOf(file)]={x:maxX?Math.max(0,Math.min(maxX,x))/maxX:0,y:maxY?Math.max(0,Math.min(maxY,y))/maxY:0};persist()}
function move(e){if(!drag||e.pointerId!==drag.pointer)return;const dx=e.clientX-drag.startX,dy=e.clientY-drag.startY;if(!drag.started&&Math.hypot(dx,dy)<7)return;if(!drag.started){drag.started=true;drag.button.setPointerCapture(e.pointerId);drag.file.classList.add('folder-dragging','folder-positioned');document.body.classList.add('folder-drag-active');}e.preventDefault();const area=workspace.getBoundingClientRect(),x=Math.max(0,Math.min(area.width-drag.rect.width,drag.rect.left-area.left+dx)),y=Math.max(0,Math.min(area.height-drag.rect.height-90,drag.rect.top-area.top+dy));drag.x=x;drag.y=y;drag.file.style.setProperty('--folder-dx',(drag.dx+x-(drag.rect.left-area.left))+'px');drag.file.style.setProperty('--folder-dy',(drag.dy+y-(drag.rect.top-area.top))+'px');const binRect=trash.getBoundingClientRect();drag.overTrash=e.clientX>=binRect.left-12&&e.clientX<=binRect.right+12&&e.clientY>=binRect.top-20&&e.clientY<=binRect.bottom+10;trash.classList.toggle('trash-drop-target',drag.overTrash);}
function finish(e,cancelled=false){if(!drag||e.pointerId!==drag.pointer)return;const finished=drag;drag=null;finished.file.classList.remove('folder-dragging');document.body.classList.remove('folder-drag-active');trash.classList.remove('trash-drop-target');if(finished.button.hasPointerCapture(e.pointerId))finished.button.releasePointerCapture(e.pointerId);if(finished.started){suppressClick=true;setTimeout(()=>suppressClick=false,350);if(!cancelled){if(finished.overTrash)remove(finished.id);else savePosition(finished.file,finished.x,finished.y)}layout();}}
document.addEventListener('pointermove',move,{passive:false});document.addEventListener('pointerup',e=>finish(e));document.addEventListener('pointercancel',e=>finish(e,true));
document.addEventListener('click',e=>{if(suppressClick&&e.target.closest('.desktop-file')){e.preventDefault();e.stopImmediatePropagation();return}if(!e.target.closest('.folder-context-menu,.folder-options'))closeMenu();if(!e.target.closest('.desktop-file,.folder-context-menu'))select(null)},true);
menu.addEventListener('click',e=>{const action=e.target.closest('[data-folder-action]')?.dataset.folderAction;if(!action||!menuKey)return;const id=menuKey;if(action==='delete')remove(id);if(action==='open'){closeMenu();openView(id)}if(action==='reset'){delete state.positions[mode()][id];persist();layout();closeMenu(true)}});
menu.addEventListener('keydown',e=>{const buttons=[...menu.querySelectorAll('button')],i=buttons.indexOf(document.activeElement);if(e.key==='Escape'){e.preventDefault();closeMenu(true)}if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();buttons[(i+(e.key==='ArrowDown'?1:-1)+buttons.length)%buttons.length].focus()}if(e.key==='Tab')closeMenu()});
const hint=document.createElement('span');hint.id='folder-drag-hint';hint.className='sr-only';hint.textContent='Drag to move. Right-click or use folder options to move to Trash. Alt and arrow keys reposition; Delete moves to Trash.';document.body.append(hint);
const layoutControl=document.createElement('button');layoutControl.className='desktop-layout-reset';layoutControl.textContent='Reset desktop layout';layoutControl.onclick=()=>{state.positions={wide:{},mobile:{}};persist();layout();notify('Folder positions reset. Deleted folders remain in Trash.')};workspace.append(layoutControl);
let resizeFrame=0;window.addEventListener('resize',()=>{cancelAnimationFrame(resizeFrame);resizeFrame=requestAnimationFrame(()=>{if(!drag)layout();closeMenu()})});window.addEventListener('blur',()=>{if(drag)finish({pointerId:drag.pointer},true);closeMenu()});
layout();
})();
